{
  "checks": [
    {
      "candidate_id": "pm",
      "verdict": "SUPPORT",
      "reason": "PM is explicitly the organizer and notification recipient. Its role name alone supplies no additional authority.",
      "sources": [
        {"quote": "PM", "clause_id": "c1", "occurrence": 0, "context_anchor": "PM must organize a review of health.log."},
        {"quote": "PM", "clause_id": "c1", "occurrence": 1, "context_anchor": "PM must be notified"}
      ]
    },
    {
      "candidate_id": "organize",
      "verdict": "SUPPORT",
      "reason": "The main predicate explicitly requires organizing a review.",
      "sources": [
        {"quote": "PM must organize a review of health.log.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "review",
      "verdict": "SUPPORT",
      "reason": "The review is the complement of organizing. UNSTATED preserves the absence of a separately stated obligation to perform or complete it.",
      "sources": [
        {"quote": "organize a review of health.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "log",
      "verdict": "SUPPORT",
      "reason": "health.log is the file to be reviewed, supporting existing-input use without an obligation to modify or generate it.",
      "sources": [
        {"quote": "a review of health.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "fatal_error",
      "verdict": "SUPPORT",
      "reason": "A fatal error is explicitly introduced within the conditional antecedent.",
      "sources": [
        {"quote": "If a fatal error appears", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "fatal_appears",
      "verdict": "SUPPORT",
      "reason": "The appearance of a fatal error is a conditional state, not an independently required occurrence.",
      "sources": [
        {"quote": "If a fatal error appears", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "stop",
      "verdict": "SUPPORT",
      "reason": "Stopping the task is explicitly required in the fatal-error branch.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "notify",
      "verdict": "SUPPORT",
      "reason": "Notification is required in the same conditional branch. The passive construction does not identify its performer.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "create",
      "verdict": "SUPPORT",
      "reason": "Creation is required in the otherwise branch; its performer is unstated.",
      "sources": [
        {"quote": "otherwise health-summary.md must be created", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "summary",
      "verdict": "SUPPORT",
      "reason": "health-summary.md is a conditional generated output, not an existing input.",
      "sources": [
        {"quote": "otherwise health-summary.md must be created", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "service",
      "verdict": "SUPPORT",
      "reason": "The service is explicitly the affected entity in the restart prohibition.",
      "sources": [
        {"quote": "The service must not be restarted.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "restart",
      "verdict": "SUPPORT",
      "reason": "Must not expresses a prohibition. The sentence stands outside the conditional branches.",
      "sources": [
        {"quote": "The service must not be restarted.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM is the explicit grammatical and participating agent of organizing.",
      "sources": [
        {"quote": "PM must organize", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r2",
      "verdict": "SUPPORT",
      "reason": "The review belongs structurally to the organizing predicate as its complement. This supports structural membership without asserting that conducting the review is independently required or completed.",
      "sources": [
        {"quote": "organize a review", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "health.log is the material reviewed, rather than a method, format or basis.",
      "sources": [
        {"quote": "review of health.log", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "The fatal error is the entity whose appearance constitutes the antecedent state.",
      "sources": [
        {"quote": "a fatal error appears", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "The fatal-error antecedent explicitly conditions stopping.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "The if-clause scopes over both coordinated obligations, including notification.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "The task is explicitly what must stop; this is not a completion condition.",
      "sources": [
        {"quote": "the task must stop", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r8",
      "verdict": "SUPPORT",
      "reason": "And explicitly conjoins stopping and notification without prescribing their sequence.",
      "sources": [
        {"quote": "the task must stop and PM must be notified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r9",
      "verdict": "SUPPORT",
      "reason": "PM receives notification; the passive wording does not make PM its performer.",
      "sources": [
        {"quote": "PM must be notified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r10",
      "verdict": "SUPPORT",
      "reason": "Otherwise binds summary creation to the alternative of the fatal-error antecedent.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified; otherwise health-summary.md must be created.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r11",
      "verdict": "SUPPORT",
      "reason": "The summary file is explicitly the result of creation.",
      "sources": [
        {"quote": "health-summary.md must be created", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r12",
      "verdict": "SUPPORT",
      "reason": "The service is the patient of the prohibited restart.",
      "sources": [
        {"quote": "The service must not be restarted", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r13",
      "verdict": "SUPPORT",
      "reason": "The task-level prohibition targets restarting. TASK denotes structural scope, not a person issuing authorization.",
      "sources": [
        {"quote": "The service must not be restarted.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "stop_condition",
      "verdict": "SUPPORT",
      "reason": "The condition references fatal-error appearance and governs stopping without requiring that appearance.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "notify_condition",
      "verdict": "SUPPORT",
      "reason": "The same antecedent governs the coordinated notification obligation.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "otherwise_state",
      "verdict": "SUPPORT",
      "reason": "The otherwise expression references the preceding fatal-error state as the operand subsequently negated; this intermediate reference does not independently impose a positive condition on creation.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified; otherwise health-summary.md must be created.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "otherwise_condition",
      "verdict": "SUPPORT",
      "reason": "Otherwise expresses the complement of the fatal-error antecedent, supporting NOT of its state reference.",
      "sources": [
        {"quote": "If a fatal error appears, the task must stop and PM must be notified; otherwise health-summary.md must be created.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    }
  ],
